package com.playsphere.chat;import com.playsphere.common.Ids;import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="conversations") public class Conversation{@Id @Column(length=36)private String id;@Column(name="conversation_type",nullable=false,length=24)private String conversationType;@Column(name="reference_id",length=36)private String referenceId;@Column(nullable=false,length=160)private String title;@Column(name="created_by_user_id",nullable=false,length=36)private String createdByUserId;@Column(name="created_at",nullable=false)private Instant createdAt;protected Conversation(){}public Conversation(String type,String ref,String title,String creator){id=Ids.uuid();conversationType=type;referenceId=ref;this.title=title;createdByUserId=creator;createdAt=Instant.now();}public String getId(){return id;}public String getConversationType(){return conversationType;}public String getReferenceId(){return referenceId;}public String getTitle(){return title;}public String getCreatedByUserId(){return createdByUserId;}public Instant getCreatedAt(){return createdAt;}}
